ALTER TABLE products
  MODIFY COLUMN name_key VARBINARY(400) NOT NULL,
  MODIFY COLUMN images_json JSON NOT NULL,
  ADD UNIQUE KEY uq_products_name_key (name_key),
  ADD CONSTRAINT chk_products_name CHECK (CHAR_LENGTH(name) > 0 AND OCTET_LENGTH(name)=OCTET_LENGTH(TRIM(name))),
  ADD CONSTRAINT chk_products_price CHECK (price_cents > 0),
  ADD CONSTRAINT chk_products_record_version CHECK (record_version > 0),
  ADD CONSTRAINT chk_products_images CHECK (JSON_TYPE(images_json)='ARRAY' AND JSON_LENGTH(images_json) BETWEEN 0 AND 3 AND (JSON_LENGTH(images_json)<1 OR (JSON_TYPE(JSON_EXTRACT(images_json,'$[0]'))='OBJECT' AND JSON_LENGTH(JSON_EXTRACT(images_json,'$[0]'))=1 AND JSON_TYPE(JSON_EXTRACT(images_json,'$[0].object_key'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(images_json,'$[0].object_key'))) BETWEEN 1 AND 1024)) AND (JSON_LENGTH(images_json)<2 OR (JSON_TYPE(JSON_EXTRACT(images_json,'$[1]'))='OBJECT' AND JSON_LENGTH(JSON_EXTRACT(images_json,'$[1]'))=1 AND JSON_TYPE(JSON_EXTRACT(images_json,'$[1].object_key'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(images_json,'$[1].object_key'))) BETWEEN 1 AND 1024 AND JSON_UNQUOTE(JSON_EXTRACT(images_json,'$[1].object_key'))<>JSON_UNQUOTE(JSON_EXTRACT(images_json,'$[0].object_key')))) AND (JSON_LENGTH(images_json)<3 OR (JSON_TYPE(JSON_EXTRACT(images_json,'$[2]'))='OBJECT' AND JSON_LENGTH(JSON_EXTRACT(images_json,'$[2]'))=1 AND JSON_TYPE(JSON_EXTRACT(images_json,'$[2].object_key'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(images_json,'$[2].object_key'))) BETWEEN 1 AND 1024 AND JSON_UNQUOTE(JSON_EXTRACT(images_json,'$[2].object_key'))<>JSON_UNQUOTE(JSON_EXTRACT(images_json,'$[0].object_key')) AND JSON_UNQUOTE(JSON_EXTRACT(images_json,'$[2].object_key'))<>JSON_UNQUOTE(JSON_EXTRACT(images_json,'$[1].object_key')))));
